UPDATE pf.workspace_file_helper SET exec_id=#{physical.execId},version=version+1 WHERE use_id=#{id} AND container_id=#{physical.containerId}
        AND image_id=#{physical.imageId} AND started_at=#{physical.startedAt} AND exec_id IS NULL
        AND NOT EXISTS(SELECT 1 FROM pf.workspace_file_helper_stop s WHERE s.use_id=pf.workspace_file_helper.use_id)
